import {createPayState,registerPayMember,payTransaction} from './member-pay-state.mjs';
export function createPilot(){const loyalty=createPayState();loyalty.merchants=[{...loyalty.merchants[0],name:'街角小店 · 示例商户',methods:['微信','人民币现金']}];const inviter=registerPayMember(loyalty,'示例推荐人');return {loyalty,inviter,member:null,orders:[],seq:0}}
export function bindPilotMember(p,name,invited=true){if(p.member)throw Error('会员已绑定，无需重复注册');p.member=registerPayMember(p.loyalty,name,invited?p.inviter.id:'');return p.member}
export function createPilotOrder(p,amount,channel){if(!p.member)throw Error('请先完成一次会员绑定');if(!Number.isFinite(amount)||amount<=0||amount>1000000||Math.abs(amount*100-Math.round(amount*100))>1e-6)throw Error('请输入有效消费金额，最多两位小数');if(!['微信','人民币现金'].includes(channel))throw Error('本轮只演示微信与现金');const m=p.loyalty.merchants[0],o={id:'PILOT-'+String(++p.seq).padStart(4,'0'),amount,channel,memberId:p.member.id,consumerRate:m.consumerRate,referralRate:m.referralRate,status:'待支付',rewardStatus:'未触发',record:null};p.orders.unshift(o);return o}
export function completePilotPayment(p,orderId,{success=true,cashier=false}={}){const o=p.orders.find(x=>x.id===orderId);if(!o)throw Error('订单不存在');if(o.record)return {order:o,replayed:true};if(!success){if(o.status==='已付款')throw Error('已确认付款不能改为支付失败');o.status='支付未成功';return {order:o}}
 if(o.channel==='人民币现金'&&!cashier)throw Error('现金必须由店员确认收款');o.status='已付款';const m=p.loyalty.merchants[0],old=[m.consumerRate,m.referralRate];try{m.consumerRate=o.consumerRate;m.referralRate=o.referralRate;o.record=payTransaction(p.loyalty,{merchantId:m.id,memberId:o.memberId,amount:o.amount,redeem:0,method:o.channel,reference:o.id,confirmed:true});o.rewardStatus='已发放';return {order:o}}catch(error){o.rewardStatus='待处理：'+error.message;return {order:o,pending:true}}finally{[m.consumerRate,m.referralRate]=old}}
